     Latah County 

     
      html,
      body,
      #viewDiv {
        padding: 0;
        margin: 0;
        height: 100%;
        width: 100%;
      }

      #topbar {
        background: #fff;
        padding: 10px;
      }

      .action-button {
        font-size: 16px;
        background-color: transparent;
        border: 1px solid #d3d3d3;
        color: #6e6e6e;
        height: 32px;
        width: 32px;
        text-align: center;
        box-shadow: 0 0 1px rgba(0, 0, 0, 0.3);
      }

      .action-button:hover,
      .action-button:focus {
        background: #0079c1;
        color: #e4e4e4;
      }

      .active {
        background: #0079c1;
        color: #e4e4e4;
      }
	  
	  
	
     

	 
	 	
	
	 
	 
	 

	 
	 

	 
	
     	
     
	
      require([
		"esri/request", 			        	
	    "esri/widgets/Sketch",
        "esri/views/MapView",		
        "esri/Map",
		"esri/Basemap",
		"esri/layers/WebTileLayer",
		"esri/layers/GraphicsLayer",
        "esri/widgets/DistanceMeasurement2D",
        "esri/widgets/AreaMeasurement2D",
		"esri/PopupTemplate",
		"esri/layers/FeatureLayer",
		"esri/widgets/ScaleBar",
		"esri/widgets/BasemapGallery",
		"esri/widgets/Expand",
		"esri/widgets/LayerList",
		"esri/widgets/Print",
		"esri/widgets/Search"
      ], function(esriRequest, Sketch, MapView, Map, Basemap, WebTileLayer, GraphicsLayer, DistanceMeasurement2D, AreaMeasurement2D,PopupTemplate, FeatureLayer, ScaleBar, BasemapGallery, Expand, LayerList, Print, Search) {
        var activeWidget = null;
		const layer = new GraphicsLayer();
				
		
		var mapBaseLayer = new WebTileLayer({
          urlTemplate:
            "https://basemaps.arcgis.com/v1/arcgis/rest/services/World_Basemap/VectorTileServer",
        });	

        var stamen = new Basemap({
          baseLayers: [mapBaseLayer],
          title: "Terrain",
          id: "terrain",
          thumbnailUrl:
            "https://stamen-tiles.a.ssl.fastly.net/terrain/10/177/409.png"
        });		

        const map = new Map({
          basemap: "satellite",
          layers: [layer]
        });

  var view = new MapView({
    container: "viewDiv",  // Reference to the scene div created in step 5
    map: map,  // Reference to the map object created before the scene
    zoom: 10,  // Sets zoom level based on level of detail (LOD)
    center: [-116.711679789558, 46.8161275055622],	// Sets center point of view using longitude,latitude
	popup: {
      dockEnabled: true,
      dockOptions: {
      buttonEnabled: false,
      breakpoint: false,
	  position: "top-right"
          }
        }
  });

         const sketch = new Sketch({
          layer: layer,
          view: view
        }); 


// change the color of features drawn using the sketch widget		
		 //*** Red stroke, 1px wide ***//
       var stroke = {
         color: [0,255,68],
         width: 2
       }

       //*** White fill color with 50% transparency ***//
       var fillColor = [255,255,255,.5];

       //*** Override all of the default symbol colors and sizes ***//
       var pointSymbol = sketch.viewModel.pointSymbol;
       pointSymbol.color = fillColor;
       pointSymbol.outline = stroke;
       pointSymbol.size = 8;

       var polylineSymbol = sketch.viewModel.polylineSymbol;
       polylineSymbol.color = stroke.color;
       polylineSymbol.width = stroke.width;

       var polygonSymbol = sketch.viewModel.polygonSymbol;
       polygonSymbol.color = fillColor;
       polygonSymbol.outline = stroke;
		
//<-- tsc - options for request -->
		var options = {
          query: {
            f: "json"
          },
          responseType: "json"
        };		

     


//4th PopupTemplate() this one is for the Fire Protection Districts layer	
      var template4 = new PopupTemplate({
          title: "Fire Protection Districts:",
          content: [{
            type: "fields",
            fieldInfos: []
          }, {
            type: "text",
            text: "<p>This property is located within the boundaries of the: <b>{FIRE_DISTR}</b>.</p>" ,
          }]
        });	

//5th PopupTemplate() this one is for the Highway Districts layer	
      var template5 = new PopupTemplate({
          title: "Highway Districts:",
          content: [{
            type: "fields",
            fieldInfos: []
          }, {
            type: "text",
            text: "<p>This property is located within the boundaries of the: <b>{HIGHWAY_DI}</b>.</p>",
          }]
        });	
		
//6th PopupTemplate() this one is for the Snowload layer	
      var template6 = new PopupTemplate({
          title: "Snowload:",
          content: [{
            type: "fields",
            fieldInfos: []
          }, {
            type: "text",
            text: "<p>This property is located within an area designated as having a: <b>{SNOW_LOAD}</b> psf roof snow load.</p>",
          }]
        });	

//7th PopupTemplate() this one is for the Zoning layer	
      var template7 = new PopupTemplate({
          title: "Zoning:",
          content: [{
            type: "fields",
            fieldInfos: []
          }, {
            type: "text",
            text: "<p>This property is zoned :<b>{ZONE_TYPE}</b>.</p>",
          }]
        });	

//8th PopupTemplate() this one is for the Sections layer	
      var template8 = new PopupTemplate({
          title: "PLSS Location:",
          content: [{
            type: "fields",
            fieldInfos: []
          }, {
            type: "text",
            text: "<p>This property is located within Section <b>{SEC_}</b> of <b>{PLSS_}</b>, B.M.</p>",
          }]
        });		
		
//9th PopupTemplate() this one is for the Herd Districts layer	
      var template9 = new PopupTemplate({
          title: "Herd Districts:",
          content: [{
            type: "fields",
            fieldInfos: []
          }, {
            type: "text",
            text: "<p>This Herd District was created by <b>{Owner}</b> on <b>{Dated}</b> .</p>",
          }]
        });	
		




		
		
// add feature layers to map

// Zoning  
		var Zoning = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Planning_Building2/MapServer/7",
		title: "Zoning Designations",
		visible: false,
		opacity: 0.6,
		showLabels: true,
		popupTemplate: template7
        });

		map.add (Zoning)
		
		//7th PopupTemplate() this one is for the Zoning layer	
      var template7 = new PopupTemplate({
          title: "Zoning:",
          content: [{
            type: "fields",
            fieldInfos: []
          }, {
            type: "text",
            text: "<p>This property is zoned :<b>{ZONE_TYPE}</b>.</p>",
          }]
        });	

		
//99th PopupTemplate() this one is for the Water and Sewer Districts layer	
      var template99 = new PopupTemplate({
          title: "Water and Sewer District:",
          content: [{
            type: "fields",
            fieldInfos: []
          }, {
            type: "text",
            text: "<p>This property is located within the boundaries of the: <b>{District}</b>.</p>",
          }]
        });		
// Water and Sewer Districts
		var WaterSewer = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/PlanningCombined/MapServer/33",
		title: "Water and Sewer Districts",
		visible: false,
		opacity: 0.6,
		popupTemplate: template99
        }); 

		map.add (WaterSewer)
		
// Topography 
		var Topography = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Planning_Building2/MapServer/9",
		title: "Topography (10ft)",
		visible: false,
        });  
		
		map.add (Topography)
  
// Roads		
		var Roads = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Transportation2/MapServer/0",
		title: "Surface Transportation",
		visible: true
        });  
		
		map.add (Roads)
// Roads		
		var Highways = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Transportation/MapServer/6",
		title: "Surface Transportation",
		listMode: "hide",
		visible: true
        });  
		
		map.add (Highways)

  
// Streams		
		var Streams = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Landscape/MapServer/1",
		title: "Streams & Waterways",
		visible: false
        });  
		
		map.add (Streams)

// Snow Load   
		var Snow = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Planning_Building3/MapServer/6",
		title: "Snow Load",
		visible: false,
		labelsVisible: true,
		popupTemplate: template6,
		opacity: 0.6
        });  
		
		map.add (Snow)
		
// School District Trustee Zones
      var schoolTrusteePopupTemplate = new PopupTemplate({
          title: "Trustee Zones:",
          content: [{
            type: "fields",
            fieldInfos: []
          }, {
            type: "text",
            text: "<p>This property is located within <b>{Trustee_Zn}</b> of the <b>{District}</b>.</p>",
          }]
        });		

	var Trustee = new FeatureLayer({
        url: "http://gis.latah.id.us/arcgis/rest/services/Districts_Precints/MapServer/6",
		title: "School District Trustee Zones",
		visible: false,
		opacity: 0.6,
		showLabels: true,
		popupTemplate: schoolTrusteePopupTemplate
        });
		map.add (Trustee);
		
// School Districts Popup		
      var template11 = new PopupTemplate({
          title: "School Districts",
          content: [{
            type: "fields",
            fieldInfos: []
          }, {
            type: "text",
            text: "<p>This Property is located with {District}.</p>",
          }]
        });		
// School Districts  
		var Schools = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Districts_Precints/MapServer/7",
		title: "School Districts",
		visible: false,
		opacity: 0.6,
		popupTemplate: template11
        }); 

		map.add (Schools)
// Rec Districts Popup			
      var template17 = new PopupTemplate({
          title: "Recreation Districts",
          content: [{
            type: "fields",
            fieldInfos: []
          }, {
            type: "text",
            text: "<p>This Property is located within the <b>{District}</b>.</p>",
          }]
        });			
// Recreation Districts  
		var Rec = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Districts_Precints2019/MapServer/4",
		title: "Recreation Districts",
		visible: false,
		opacity: 0.6,
		popupTemplate: template17
        }); 

		map.add (Rec)

// Postal Code Areas  
		var PostalCode = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Districts_Precints/MapServer/0",
		title: "Postal Code Areas",
		visible: false,
		opacity: 0.6
        }); 

		map.add (PostalCode)	
// Parcels		
			var options = {
			  query: {
				f: "json"
			  },
			  responseType: "json"
		};		
		
		function callRestSvc(value, key, data){
				var url = "https://api.latah.id.us/maps/AssessedData?parcel=" + value.graphic.attributes.PARCEL_ID + "A";
				return esriRequest(url, options).then(function(response) {            							
					return response.data.AssessedDataResult;		
			  }).otherwise(function(error){
					return("Error: ", error.message);
			  });						
		};
		
        var Parcels = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Parcels1/MapServer/0",
		title: "Parcel Boundaries",
		outFields: ["*"],
		popupTemplate: {
			title: "Parcel Assessment: {PM_PAR_14}",
			content: callRestSvc
			}	
		});
		
        map.add(Parcels);
		
		
// Palouse Prairie  
		var Prairie = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/PrairieRemnant/MapServer/0",
		title: "Palouse Prairie Remnant",
		visible: false
        }); 

		map.add (Prairie)	

// Incorporated Places  
		var Cities = new FeatureLayer({
		url: "https://gis.latah.id.us/arcgis/rest/services/Planning_Building2/MapServer/31",
		title: "Incorporated Places",
		visible: false,
		});
		
		map.add(Cities);
// Highway Districts
		var Highways = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Districts_Precints/MapServer/5",
		title: "Highway Districts",
		visible: false,
		opacity: 0.6,
		popupTemplate: template5
        }); 

		map.add (Highways)
		

// Herd Districts  
		var Herds = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Districts_Precints/MapServer/2",
		title: "Herd Districts",
		visible: false,
		opacity: 0.6,
		popupTemplate: template9
        }); 

		map.add (Herds)
// Floodplains 
		var Floodplains = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Planning_Building3/MapServer/4",
		visible: false,
		title: "Flood Plains"
        });  
		
		map.add (Floodplains)
// Fire Districts		
		var Fire = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Districts_Precints/MapServer/8",
		title: "Fire Protection Districts",
		visible: false,
		opacity: 0.6,
		popupTemplate: template4
        }); 
		
		map.add (Fire) 
// PopupTemplate this one is for the Comprehensive Plan layer	
      var template14 = new PopupTemplate({
          title: "Comprehensive Plan:",
          content: [{
            type: "fields",
            fieldInfos: []
          }, {
            type: "text",
            text: "<p>This property is located within a portion of Latah County designated <b>{ZONE}</b> ({Desigtn}).</p>",
          }]
        });			
// Comprehensive Plan  
		var Comp = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Planning_Building3/MapServer/5",
		title: "Comprehensive Plan",
		visible: false,
		opacity: 0.6,
		popupTemplate: template14
        });  
		
		map.add (Comp)
// Commissioner Districts Popup		
      var template10 = new PopupTemplate({
          title: "Commissioner District",
          content: [{
            type: "fields",
            fieldInfos: []
          }, {
            type: "text",
            text: "<p>This Property is located in Latah County {District}, and is represented by Commissioner {Comssnr}.</p>",
          }]
        });			
// Commissioner Districts  
		var Commissioner = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Districts_Precints/MapServer/3",
		title: "Commissioner Districts",
		visible: false,
		opacity: 0.6,
		popupTemplate: template10
        }); 

		map.add (Commissioner)
// Cemetery Districts Popup		
      var template12 = new PopupTemplate({
          title: "Cemetery Districts",
          content: [{
            type: "fields",
            fieldInfos: []
          }, {
            type: "text",
            text: "<p>This Property is located within the <b>{District}</b>.</p>",
          }]
        });			
// Cemetery Districts  
		var Cemetery = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Districts_Precints2019/MapServer/9",
		title: "Cemetery Districts",
		visible: false,
		opacity: 0.6,
		popupTemplate: template12
        }); 

		map.add (Cemetery)
// Areas of City Impact 
		var Impact = new FeatureLayer({
        url: "https://gis.latah.id.us/arcgis/rest/services/Planning_Building3/MapServer/1",
		title: "Areas of City Impact",
		visible: false,
		opacity: 0.6
        });  
		
		map.add (Impact)  	
// Addresses		
		var Addresses = new FeatureLayer({
		url: "https://gis.latah.id.us/arcgis/rest/services/Planning_Building2/MapServer/0",
		title: "Address Points"
		});
		
		map.add(Addresses);


// Sections   
		var Sections = new FeatureLayer({
		listMode: "hide",
        url: "https://gis.latah.id.us/arcgis/rest/services/Cadastral_Data_/MapServer/2"
        });

        map.add(Sections);
// Townships  
        var Townships = new FeatureLayer({
		listMode: "visible",
        url: "https://gis.latah.id.us/arcgis/rest/services/Cadastral_Data_/MapServer/1"
        });

        map.add(Townships); 
// PLSS Labels  		
		var Labels = new FeatureLayer({
		listMode: "hide",
        url: "https://gis.latah.id.us/arcgis/rest/services/Cadastral_Data_/MapServer/0"
        });

        map.add(Labels);

		
// add sketch widget to view  
view.ui.add(sketch, "top-right"); 
        
// create scale bar 
var scaleBar = new ScaleBar({
view: view});  
// add scale bar
view.ui.add(scaleBar, {
  position: "bottom-left"}); 

// create base map gallery
var basemapGallery = new BasemapGallery({
  view: view,
  container: document.createElement("div")
});    
// create container for base map gallery 
var bgExpand = new Expand({
view: view,
content: basemapGallery
}); 
// add container with base map gallery
view.ui.add(bgExpand, "bottom-left");

// create layer list  
var layerList = new LayerList({
  view: view,
  container: document.createElement("div")
}); 
// create container for layerList 
var llExpand = new Expand({
view: view,
content: layerList
});
// add container with layerList
view.ui.add(llExpand, "top-left");  
  
// create print widget
var print = new Print({
  view: view,
  printServiceUrl: "https://gis.latah.id.us/arcgis/rest/services/Utilities/PrintingTools/GPServer/Export%20Web%20Map%20Task"}); 
// create container for print widget
var pwExpand = new Expand({
view: view,
content: print
}); 
// add container with layerList
view.ui.add(pwExpand, "bottom-right"); 
   	
// add the toolbar for the measurement widgets
        view.ui.add("topbar", "top-right");

        document
          .getElementById("distanceButton")
          .addEventListener("click", function() {
            setActiveWidget(null);
            if (!this.classList.contains("active")) {
              setActiveWidget("distance");
            } else {
              setActiveButton(null);
            }
          });

        document
          .getElementById("areaButton")
          .addEventListener("click", function() {
            setActiveWidget(null);
            if (!this.classList.contains("active")) {
              setActiveWidget("area");
            } else {
              setActiveButton(null);
            }
          });

        function setActiveWidget(type) {
          switch (type) {
            case "distance":
              activeWidget = new DistanceMeasurement2D({
				viewModel: {
                view: view,
				unit: "us-feet",
				mode: "geodesic"
				}
              });

              // skip the initial 'new measurement' button
              activeWidget.viewModel.newMeasurement();

              view.ui.add(activeWidget, "top-right");
              setActiveButton(document.getElementById("distanceButton"));
              break;
            case "area":
              activeWidget = new AreaMeasurement2D({
                viewModel:{
				view: view,
				mode: "geodesic",
				unit: "acres"
				}
              });

              // skip the initial 'new measurement' button
              activeWidget.viewModel.newMeasurement();

              view.ui.add(activeWidget, "top-right");
              setActiveButton(document.getElementById("areaButton"));
              break;
            case null:
              if (activeWidget) {
                view.ui.remove(activeWidget);
                activeWidget.destroy();
                activeWidget = null;
              }
              break;
          }
        }

        function setActiveButton(selectedButton) {
          // focus the view to activate keyboard shortcuts for sketching
          view.focus();
          var elements = document.getElementsByClassName("active");
          for (var i = 0; i < elements.length; i++) {
            elements[i].classList.remove("active");
          }
          if (selectedButton) {
            selectedButton.classList.add("active");
          }
        }

 // create & define search widget  
var searchWidget = new Search({
view: view,
includeDefaultSources: false,
locationEnabled: false,
maxSuggestions: 80,
sources: [{
layer: Parcels,
searchFields: ["PM_PAR_14"],
displayField: "PM_PAR_14",
exactMatch: false,
outFields: ["PARCEL_ID"],
name: "Parcel Number",
placeholder: "example: RP40N02W162502",
}, {
layer: Addresses,
searchFields: ["FULLADDRSS"],
exactMatch: false,
outFields: ["FULLADDRSS"],
name: "Address",
    }]
});

// add search widget  
view.ui.add(searchWidget, {
  position: "top-left",
  index: 0
}); 	
	 
	 });
     
   
   
   	  
     
       
       
     
